import{_ as d,C as h,o as r,c as u,a2 as i,b as s,w as t,a,E as c,a3 as l,j as o}from"./chunks/framework.mrTIYZc5.js";const b=JSON.parse('{"title":"System Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),p={name:"guide/architecture.md"};function m(g,e,f,A,S,y){const n=h("Mermaid");return r(),u("div",null,[e[2]||(e[2]=i('<h1 id="system-architecture" tabindex="-1">System Architecture <a class="header-anchor" href="#system-architecture" aria-label="Permalink to &quot;System Architecture&quot;">​</a></h1><p>Docker Secret Operator (DSO) is built on an event-driven, micro-kernel architecture designed for high-security container environments. It operates as a bridge between specialized secret providers (Vaults) and the Docker Engine.</p><h2 id="core-components" tabindex="-1">Core Components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core Components&quot;">​</a></h2><p>The DSO binary encapsulates four primary internal engines that coordinate the secret lifecycle.</p><h3 id="_1-watcher-engine" tabindex="-1">1. Watcher Engine <a class="header-anchor" href="#_1-watcher-engine" aria-label="Permalink to &quot;1. Watcher Engine&quot;">​</a></h3><p>The Watcher is the &quot;Eyes&quot; of the system. It maintains two concurrent observation steams:</p><ul><li><strong>Provider Stream</strong>: Performs periodic polling/long-polling of cloud secret managers (AWS, Azure, Vault). It uses hashing to detect &quot;Secret Drift&quot; without reading the actual secret value unless a change is confirmed.</li><li><strong>Docker Event Stream</strong>: Listens to the <code>/events</code> endpoint of the Docker Unix socket. This ensures that manually restarted containers or new deployments are immediately intercepted and injected with the latest secrets.</li></ul><h3 id="_2-reloader-controller" tabindex="-1">2. Reloader Controller <a class="header-anchor" href="#_2-reloader-controller" aria-label="Permalink to &quot;2. Reloader Controller&quot;">​</a></h3><p>The Reloader is the &quot;Brain&quot; of the system. When the Watcher detects a drift or a new container event, the Reloader:</p><ol><li>Identifies affected containers based on labels (<code>dso.reloader=true</code>).</li><li>Selects an <strong>Atomic Rotation Strategy</strong> (Rolling, SIGHUP, or Restart).</li><li>Coordinates the sequence of injection and verification.</li></ol><h3 id="_3-tar-streamer" tabindex="-1">3. Tar Streamer <a class="header-anchor" href="#_3-tar-streamer" aria-label="Permalink to &quot;3. Tar Streamer&quot;">​</a></h3><p>The Tar Streamer is the &quot;Hands&quot; of the system and DSO&#39;s core security innovation. Instead of writing secrets to the host filesystem and mounting them (which risks persistence on disk), the Tar Streamer:</p><ol><li>Generates an in-memory TAR archive containing the secret files.</li><li>Streams this archive directly into the target container&#39;s filesystem via the <code>CopyToContainer</code> Docker API.</li><li>Injects the files into a <code>tmpfs</code> (RAM-backed) mount point within the container.</li></ol><h3 id="_4-provider-rpc-layer" tabindex="-1">4. Provider RPC Layer <a class="header-anchor" href="#_4-provider-rpc-layer" aria-label="Permalink to &quot;4. Provider RPC Layer&quot;">​</a></h3><p>DSO uses a plugin-based provider model. Each provider (AWS, Vault, etc.) runs as an isolated Go process. This ensures that a failure or vulnerability in a specific cloud SDK cannot compromise the core DSO agent or other providers.</p><hr><h2 id="technical-workflows" tabindex="-1">Technical Workflows <a class="header-anchor" href="#technical-workflows" aria-label="Permalink to &quot;Technical Workflows&quot;">​</a></h2><h3 id="the-synchronization-loop-reconciliation" tabindex="-1">The Synchronization Loop (Reconciliation) <a class="header-anchor" href="#the-synchronization-loop-reconciliation" aria-label="Permalink to &quot;The Synchronization Loop (Reconciliation)&quot;">​</a></h3>',18)),(r(),s(l,null,{default:t(()=>[c(n,{id:"mermaid-89",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20participant%20Vault%20as%20Cloud%20Secret%20Manager%0A%20%20%20%20participant%20Watcher%20as%20Watcher%20Engine%0A%20%20%20%20participant%20Reloader%20as%20Reloader%20Controller%0A%20%20%20%20participant%20Streamer%20as%20Tar%20Streamer%0A%20%20%20%20participant%20Docker%20as%20Docker%20Engine%0A%0A%20%20%20%20Watcher-%3E%3EVault%3A%20Check%20Secret%20Hash%20(SHA-256)%0A%20%20%20%20Vault--%3E%3EWatcher%3A%20Hash%20Mismatch%20Detected%0A%20%20%20%20Watcher-%3E%3EReloader%3A%20Trigger%20Refresh%20for%20'app-prod'%0A%20%20%20%20Reloader-%3E%3EVault%3A%20Fetch%20Full%20Secret%20Value%20(Memory-Only)%0A%20%20%20%20Reloader-%3E%3EStreamer%3A%20Generate%20In-Memory%20Tarball%0A%20%20%20%20Streamer-%3E%3EDocker%3A%20Stream%20Tarball%20to%20Container%20(Atomic)%0A%20%20%20%20Docker--%3E%3EReloader%3A%20200%20OK%20(Injected%20to%20%2Frun%2Fsecrets)%0A%20%20%20%20Reloader-%3E%3EWatcher%3A%20Reconciliation%20Complete%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("h3",{id:"event-driven-injection",tabindex:"-1"},[a("Event-Driven Injection "),o("a",{class:"header-anchor",href:"#event-driven-injection","aria-label":'Permalink to "Event-Driven Injection"'},"​")],-1)),e[4]||(e[4]=o("p",null,"When a new container starts, DSO intercepts the standard Docker lifecycle to ensure secrets are present before the entrypoint executes.",-1)),(r(),s(l,null,{default:t(()=>[c(n,{id:"mermaid-96",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20Engine%20as%20Docker%20Engine%0A%20%20%20%20participant%20Watcher%20as%20Watcher%20Engine%0A%20%20%20%20participant%20Reloader%20as%20Reloader%20Controller%0A%20%20%20%20%0A%20%20%20%20Engine-%3E%3EWatcher%3A%20Event%3A%20container.start%20(id%3A%20abc)%0A%20%20%20%20Watcher-%3E%3EReloader%3A%20Intercept%20Start%0A%20%20%20%20Reloader-%3E%3EReloader%3A%20Check%20Labels%20(dso.reloader%3Dtrue)%0A%20%20%20%20Reloader-%3E%3EReloader%3A%20Fetch%20Secrets%0A%20%20%20%20Reloader-%3E%3EEngine%3A%20Inject%20Secrets%20to%20'abc'%0A%20%20%20%20Reloader-%3E%3EEngine%3A%20Resume%20Container%20Start%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=i('<h2 id="security-boundaries" tabindex="-1">Security Boundaries <a class="header-anchor" href="#security-boundaries" aria-label="Permalink to &quot;Security Boundaries&quot;">​</a></h2><ul><li><strong>Process Memory</strong>: Secrets reside in the <code>dso-agent</code> heap only during the injection window.</li><li><strong>Unix Socket</strong>: All communication between the DSO CLI and Agent happens over a restricted Unix socket (<code>/run/docker/plugins/dso.sock</code>).</li><li><strong>No Disk I/O</strong>: The system is designed to operate on read-only filesystems. It never requires write access to the host disk for secret handling.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><strong><a href="/docs/guide/security.html">Security Model</a></strong>: Deep dive into the threat mititagtion.</li><li><strong><a href="/docs/guide/configuration.html">Configuration</a></strong>: How to define providers and mappings.</li><li><strong><a href="/docs/guide/production-readiness.html">Production Readiness</a></strong>: Best practices for deployment.</li></ul>',4))])}const k=d(p,[["render",m]]);export{b as __pageData,k as default};
